document.addEventListener("DOMContentLoaded", function () {
    const btnsBack = document.querySelectorAll('.btn.btn__back--l-arrow');
    btnsBack.forEach((el) => {
        el.addEventListener('click', () => {
            const referrer = document.referrer;
            if (referrer) {
                window.location.href = referrer;
            } else {
                window.history.back();
            }
        });
    });
});